tool_args.content:
{
  "experiment": "exp-013-constraint-ablation",
  "description": "Constraint aggregation ablation: MaxSAT vs count-only vs random-weight",
  "data_sources": {
    "exp033_mistral_7b_folio204": "folio",
    "exp046_mistral_7b_pw600": "proofwriter"
  },
  "model": "Mistral-7B-Instruct-v0.3",
  "n_problems": 804,
  "k": 12,
  "n_random_trials": 10,
  "methods": {
    "maxsat": {
      "description": "Original SICA: Z3 dedup + MaxSAT satisfiability + scorer (pre-computed)",
      "accuracy": 0.4229,
      "correct": 340
    },
    "count_only": {
      "description": "Raw constraint count per answer (no Z3 dedup, no satisfiability check)",
      "accuracy": 0.4216,
      "correct": 339
    },
    "random_weight": {
      "description": "Random uniform [0,1] weight per constraint, sum per answer (10 trials)",
      "accuracy_mean": 0.4206,
      "accuracy_std": 0.0042
    },
    "sc_baseline": {
      "description": "Self-consistency majority vote (trace count only)",
      "accuracy": 0.4316,
      "correct": 347
    }
  },
  "deltas_pp": {
    "maxsat_vs_countonly": 0.12,
    "maxsat_vs_random": 0.22,
    "maxsat_vs_sc": -0.87,
    "countonly_vs_sc": -1.00
  },
  "agreement": {
    "maxsat_vs_countonly": 0.944,
    "countonly_vs_sc": 0.919
  },
  "disagreement_maxsat_vs_countonly": {
    "total": 45,
    "maxsat_wins": 18,
    "count_wins": 17,
    "both_wrong": 10
  },
  "per_dataset": {
    "folio": {
      "n": 204,
      "maxsat_acc": 0.5931,
      "count_only_acc": 0.5686,
      "sc_acc": 0.5441,
      "agree_rate": 0.917
    },
    "proofwriter": {
      "n": 600,
      "maxsat_acc": 0.3650,
      "count_only_acc": 0.3717,
      "sc_acc": 0.3933,
      "agree_rate": 0.953
    }
  }
}
